actions.script:
const L = (text) => ec.l10n.localize(text)
const say = (template, values) => String(L(template)).replace(/\$\{(\w+)\}/g, (all, name) => String((values || {})[name] ?? ''))
const out = ec.service.sync().name('org.moqui.admin.CertificateServices.get#Certificates').call() || {}
const STATES = {AcmeOrdering: [L('Ordering'), 'info'], AcmeIssued: [L('Issued'), 'positive'], AcmeFailed: [L('Failed'), 'negative']}
const host = (url) => String(url || '').replace(/^https:\/\//, '').replace(/[/:].*$/, '')
const authority = (url) => url === out.stagingUrl ? L('Let\'s Encrypt staging')
    : host(url) === 'acme-v02.api.letsencrypt.org' ? L('Let\'s Encrypt') : host(url)
listenText = out.listenPort != null ? say('The HTTPS listener is on port ${port}.', {port: out.listenPort})
    : L('The HTTPS listener is not running: with no certificate in runtime/cert it starts when a name is set up with ACME, and then answers only that name\'s challenge until its certificate is there.')
challengePort = out.challengePort ?? 443
certificateList = Array.from(out.certificateList || []).map((entry) => {
    const cert = entry.certificate
    const acme = entry.acme
    let certText, certLabel, certColor, fileText = ''
    if (!cert) {
        certText = L('HTTPS for this name is refused')
        certLabel = L('None')
        certColor = 'negative'
    } else if (cert.problem) {
        certText = L('It does not load, so HTTPS for this name is refused')
        certLabel = L('Not usable')
        certColor = 'negative'
        fileText = cert.file + ': ' + cert.problem
    } else {
        const days = Number(cert.daysLeft)
        const until = cert.notAfter != null ? ec.l10n.format(new Date(Number(cert.notAfter)), 'yyyy-MM-dd') : ''
        certText = (cert.issuer || L('Unknown issuer')) + (until ? ' · ' + L('until') + ' ' + until : '') +
            (cert.daysLeft != null ? ' (' + (days < 0 ? L('expired') : say('${days} days', {days})) + ')' : '')
        certColor = days < 0 ? 'negative' : days < 14 ? 'warning' : 'positive'
        certLabel = days < 0 ? L('Expired') : days < 14 ? L('Expires soon') : L('Valid')
        const by = cert.matchKind === 'default' ? L('the default certificate') : cert.matchKind === 'wildcard'
            ? say('the wildcard of ${name}', {name: String(cert.pair).replace(/^_wildcard\./, '')}) : ''
        fileText = cert.file + ' (' + (cert.acmeWritten ? L('ACME, set up here') : cert.layout) + ')' + (by ? ' · ' + by : '')
    }
    const [stateLabel, stateColor] = acme ? (STATES[acme.statusId] || [L('Set up'), 'info']) : [L('Not set up'), 'grey']
    let acmeText = ''
    if (acme) {
        const parts = [authority(acme.directoryUrl)]
        parts.push(acme.renewing ? L('renewed before it runs out') : L('not renewed'))
        if (acme.lastAttemptDate) parts.push(L('last tried') + ' ' + ec.l10n.format(new Date(Number(acme.lastAttemptDate)), ''))
        if (acme.statusId === 'AcmeFailed' && acme.lastError) parts.push(acme.lastError)
        if (acme.shadowed) parts.push(L('another certificate file for this name is served before it; remove that file to serve this one'))
        acmeText = parts.join(' · ')
    }
    return {hostName: entry.hostName, reasonsText: Array.from(entry.reasons || []).join(', '), certText, certLabel, certColor, fileText,
        stateLabel, stateColor, acmeText, setUp: !!acme, renewing: !!acme?.renewing, ordering: !!acme?.ordering}
})
hostOptions = certificateList.filter((row) => !row.setUp).map((row) => ({hostName: row.hostName}))
directoryOptions = [{key: out.directoryUrl, text: authority(out.directoryUrl)},
    {key: out.stagingUrl, text: L('Let\'s Encrypt staging: test certificates, for a first try')},
    {key: 'other', text: L('Another authority')}]
